local function BindCandidateRow(row, candidate, index)
    local finder = Finder()
    row.invite:SetText(IsRequest(candidate) and REQUEST_INVITE or GROUP_INVITE)
    local inviteWidth = math.max(140, row.invite:GetFontString():GetStringWidth() + 24)
    local whisperWidth = math.max(110, row.whisper:GetFontString():GetStringWidth() + 24)
    row.invite:SetWidth(inviteWidth)
    row.whisper:SetWidth(whisperWidth)
    local width = math.max(80, row:GetWidth() - inviteWidth - whisperWidth - 48)
    row.name:SetText(PlainName(candidate.name or candidate.key))
    row.name:SetWidth(math.min(math.max(20, width - 66), math.max(20, row.name:GetStringWidth())))
    local protocol = APR.PartyFinderProtocol
    local atlas = protocol and protocol.LanguageAtlas(candidate.primary)
    local atlasAvailable = atlas and (not C_Texture or not C_Texture.GetAtlasInfo or C_Texture.GetAtlasInfo(atlas))
    if atlasAvailable then row.flag:SetAtlas(atlas); row.flag:Show() else row.flag:Hide() end
    row.languageFallback:SetText(candidate.primary and candidate.primary:sub(1, 2):upper() or "?")
    row.languageFallback:SetShown(not atlasAvailable)
    local extra = math.max(0, #(candidate.spokenLanguages or {}) - 1)
    row.extraLanguages:SetText(extra > 0 and ("+" .. extra) or "")
    row.extraLanguages:SetShown(extra > 0)
    local classInfo = C_CreatureInfo and C_CreatureInfo.GetClassInfo and C_CreatureInfo.GetClassInfo(candidate.class)
    local className = classInfo and classInfo.className or tostring(candidate.class or "")
    local details = string.format(L["GF_LEVEL_CLASS"], candidate.level or 0, className)
    if (candidate.groupSize or 0) > 1 then details = details .. " · " .. string.format(L["GF_GROUP_SIZE"], candidate.groupSize) end
    if candidate.afk then details = details .. " · " .. (AFK or "AFK") end
    if candidate.dnd then details = details .. " · " .. (DND or "DND") end
    row.details:SetWidth(width); row.details:SetText(details)
    row.progress:SetWidth(width)
    local progress = finder and finder:GetCandidateDescription(candidate) or L["GF_SAME_ZONE"]
    row.progress:SetText(candidate.status and (L["GF_INVITE_" .. candidate.status] .. " · " .. progress) or progress)
    row.age:SetText(string.format(L["GF_LAST_SEEN"], math.max(0, math.floor((GetTime and GetTime() or 0) - (candidate.seenAt or 0)))))
    local allowed, reason = false, nil
    if finder then allowed, reason = finder:CanInvite(candidate) end
    row.invite:SetEnabled(allowed == true)
    row.inviteReason = reason
    UI:SetListRowState(row, false, index == #(Panel.items or {}))
end--[[APR_DIAG]]; BindCandidateRow = APRTrace("APR-Core/ui/panels/PartyFinderPanel.lua:106:BindCandidateRow#12", BindCandidateRow)--[[/APR_DIAG]]

